import React, { useState, useRef, useEffect } from 'react';
import Tips from '../Tips/Tips';
import Employees from '../Employees/Employees';
import Summary from '../Summary/Summary';
import './Tabs.css';

const Tabs = () => {
  const [activeTab, setActiveTab] = useState(0);
  const [indicatorStyle, setIndicatorStyle] = useState({});
  const tabRefs = useRef([]);

  const tabs = [
    { title: 'Add Tips', icon: '+', component: Tips },
    { title: 'Manage Employees', icon: '🚚', component: Employees },
    { title: 'Returns', icon: 'ⓘ', component: Summary },
  ];

  useEffect(() => {
    const activeTabElement = tabRefs.current[activeTab];
    if (activeTabElement) {
      const { offsetLeft, offsetWidth } = activeTabElement;
      setIndicatorStyle({
        left: `${offsetLeft}px`,
        width: `${offsetWidth}px`,
      });
    }
  }, [activeTab]);

  return (
    <div className="tabs">
      <ul>
        {tabs.map((tab, index) => (
          <li key={index}>
            <button
              ref={(el) => (tabRefs.current[index] = el)}
              className={index === activeTab ? 'active' : ''}
              onClick={() => setActiveTab(index)}
            >
              {tab.icon} {tab.title}
            </button>
          </li>
        ))}
      </ul>
      <div className="slider">
        <div className="indicator" style={indicatorStyle}></div>
      </div>
      <div className="content">
        {tabs.map((tab, index) => (
          <section key={index} style={{ display: index === activeTab ? 'block' : 'none' }}>
            <h2>{tab.title}</h2>
            {tab.component ? <tab.component /> : <p>{tab.content}</p>}
          </section>
        ))}
      </div>
    </div>
  );
};

export default Tabs;
